#!/bin/sh
# Generated by FWShift: the rule tables of one Cisco Meraki MX network, put through the Dashboard API (v1).
# Read the report first: what is not written is listed there. Each put replaces the whole table.
# Usage: MERAKI_API_KEY=... NETWORK_ID=N_... [MERAKI_BASE=https://api.meraki.com/api/v1] [DRY_RUN=1] sh this-file
# DRY_RUN=1 only writes the bodies, and needs no key. The backups (before-*.json) end in the fixed default rule of the
# MX: to put a backup back, remove that last rule (comment "Default rule") from its rules first.
set -eu
OUT="${OUT:-meraki-$(date +%Y%m%d%H%M%S)}"
mkdir -p "$OUT"
api() {  # api METHOD PATH [BODY-FILE]
  tries=0
  while :; do
    if [ -n "${3:-}" ]; then
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Content-Type: application/json' -H 'Accept: application/json' --data-binary @"$3" "$MERAKI_BASE$2")
    else
      code=$(curl -sS -o "$OUT/last.json" -D "$OUT/last.hdr" -w '%{http_code}' -X "$1" -H "Authorization: Bearer $MERAKI_API_KEY" \
             -H 'Accept: application/json' "$MERAKI_BASE$2")
    fi
    case "$code" in
      2??) cat "$OUT/last.json"; return 0 ;;
      429) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "rate limited: $2" >&2; return 1; }
           wait=$(sed -n 's/^[Rr]etry-[Aa]fter: *\([0-9]*\).*/\1/p' "$OUT/last.hdr"); sleep "${wait:-2}" ;;
      *) echo "HTTP $code on $1 $2:" >&2; cat "$OUT/last.json" >&2; return 1 ;;
    esac
  done
}
cat > "$OUT/l3FirewallRules.json" <<'FWSHIFT_EOF'
{
 "rules": [
  {
   "comment": "pf line 72: block out quick on $dmz_if proto tcp from any to $mail_srv port telnet",
   "policy": "deny",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "23",
   "destCidr": "10.20.1.25/32",
   "syslogEnabled": false
  },
  {
   "comment": "pf line 75: block out on $dmz_if proto udp to $dmz_net port { 137:139 }",
   "policy": "deny",
   "protocol": "udp",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "137-139",
   "destCidr": "10.20.1.0/24",
   "syslogEnabled": false
  },
  {
   "comment": "pf line 46: block all",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  },
  {
   "comment": "pf line 47: block in quick from <bogons> label \"bogons\"",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "0.0.0.0/8,127.0.0.0/8,169.254.0.0/16,192.0.2.0/24,240.0.0.0/4",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  },
  {
   "comment": "pf line 81: block return-rst in on $int_if proto tcp to port 113",
   "policy": "deny",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "113",
   "destCidr": "Any",
   "syslogEnabled": false
  },
  {
   "comment": "pf line 54: block in on $int_if proto tcp from any to any port 6000:6010",
   "policy": "deny",
   "protocol": "tcp",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "6000-6010",
   "destCidr": "Any",
   "syslogEnabled": false
  },
  {
   "comment": "pf line 46: block all",
   "policy": "deny",
   "protocol": "any",
   "srcPort": "Any",
   "srcCidr": "Any",
   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  }
 ],
 "syslogDefaultRule": false
}
FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
# Not written:
#   line 41: the source of the rule is in zone em0, and the MX names no zone: give the networks behind em0 with --zone-network
#   antispoof em1 network: references 'em1 network': the network of em1 is not in pf.conf; give it with --interface-address INTERFACE=ADDRESS/BITS
#   antispoof em1 address: references 'em1 address': the address of em1 is not in pf.conf; give it with --interface-address INTERFACE=ADDRESS/BITS
#   brute force: references 'bruteforce': it has no addresses in pf.conf: they are added at run time (pfctl -T add, overload)
#   line 49: references 'spamd': its addresses are read from '/etc/mail/spamd.list' when the rules are loaded, which is not in pf.conf
#   admin ssh: references 'em2 network': the network of em2 is not in pf.conf; give it with --interface-address INTERFACE=ADDRESS/BITS; the source of the rule is in zone em1, and the MX names no zone: give the networks behind em1 with --zone-network
#   line 92: not converted: the user of the socket (user proxy), which only traffic of the firewall itself has; the source of the rule is in zone em1, and the MX names no zone: give the networks behind em1 with --zone-network
